//! Cross-language PARG artifact gate: the committed fixture
//! (`fixtures/pg/demo.json`) is generated by the Ruby compiler
//! (`Parsanol::PARG`). If Rust can verify its checksum, extract the grammar
//! and parse with it, Ruby and Rust agree on the artifact contract.

use parsanol::parg::{canonical_json, PargError};
use parsanol::portable::{AstArena, PortableParser};
use parsanol::PargArtifact;

const FIXTURE: &str = include_str!("fixtures/pg/demo.json");
const SEALED_FIXTURE: &str = include_str!("fixtures/pg/demo-sealed.json");
const CANONICAL_SAMPLE: &str = include_str!("fixtures/pg/canonical_sample.json");

#[test]
fn loads_and_verifies_the_ruby_compiled_fixture() {
    let artifact = PargArtifact::from_json(FIXTURE).expect("fixture must verify");
    assert_eq!(artifact.version(), Some("1.2.0"));
    assert_eq!(artifact.grammar_name(), Some("Demo"));
    assert_eq!(artifact.shape(), Some("parsanol-tree/v2"));
    assert_eq!(artifact.entry_names(), vec!["identifier"]);
    assert_eq!(artifact.entry_root("identifier").unwrap(), "iso_identifier");
    assert!(artifact
        .source()
        .unwrap()
        .starts_with("grammar Demo version"));
    assert!(artifact.checksum().unwrap().starts_with("sha256:"));
}

#[test]
fn rejects_a_tampered_envelope() {
    let mut value: serde_json::Value = serde_json::from_str(FIXTURE).unwrap();
    value["version"] = serde_json::Value::String("9.9.9".into());
    let text = serde_json::to_string(&value).unwrap();
    match PargArtifact::from_json(&text) {
        Err(PargError::ChecksumMismatch {
            stored, computed, ..
        }) => {
            assert!(stored.starts_with("sha256:"));
            assert!(computed.starts_with("sha256:"));
            assert_ne!(stored, computed);
        }
        other => panic!("expected checksum mismatch, got {other:?}"),
    }
}

/// ruby#443 sealed artifacts (1.3.131+) carry `byte_checksum` and the
/// `validated` receipt. The canonical payload excludes both `checksum`
/// and `byte_checksum`, so a sealed artifact verifies on loaders that
/// only see a parsed envelope (wasm/FFI) — rs#397.
#[test]
fn loads_a_sealed_ruby_artifact_through_the_canonical_tier() {
    let artifact = PargArtifact::from_json(SEALED_FIXTURE).expect("sealed fixture must verify");
    assert_eq!(artifact.grammar_name(), Some("Demo"));
    assert!(artifact.checksum().unwrap().starts_with("sha256:"));
}

/// The canonical payload is "everything except checksum and
/// byte_checksum" — including the `validated` receipt. A loader that
/// only sees a parsed envelope (no exact bytes, so no byte tier — the
/// wasm/FFI shape) must still verify a sealed artifact's content.
#[test]
fn canonical_tier_covers_a_parsed_sealed_envelope() {
    let mut value: serde_json::Value = serde_json::from_str(SEALED_FIXTURE).unwrap();
    value.as_object_mut().unwrap().remove("byte_checksum");
    let text = serde_json::to_string(&value).unwrap();
    PargArtifact::from_json(&text)
        .unwrap_or_else(|err| panic!("parsed sealed envelope must verify: {err:?}"));
}

/// When the byte_checksum region is present it is strict: the text it
/// travels with must hash to it, even when the canonical payload is
/// otherwise valid.
#[test]
fn byte_tier_rejects_a_stored_digest_that_does_not_match_the_text() {
    let mut value: serde_json::Value = serde_json::from_str(SEALED_FIXTURE).unwrap();
    value["byte_checksum"] = serde_json::Value::String(format!("sha256:{}", "f".repeat(64)));
    let text = serde_json::to_string(&value).unwrap();
    match PargArtifact::from_json(&text) {
        Err(PargError::ChecksumMismatch { stored, .. }) => {
            assert!(stored.ends_with(&"f".repeat(16)));
        }
        other => panic!("expected byte-tier mismatch, got {other:?}"),
    }
}

/// The byte tier guards the exact file bytes, not just the content: a
/// trailing-newline flip leaves the parsed envelope (and therefore the
/// canonical payload) untouched, so the rejection can only come from
/// the byte tier — which runs before any canonical work.
#[test]
fn byte_tier_rejects_a_flip_that_leaves_the_canonical_payload_intact() {
    assert!(SEALED_FIXTURE.ends_with("}\n"));
    let tampered = format!("{SEALED_FIXTURE}\n");
    match PargArtifact::from_json(&tampered) {
        Err(PargError::ChecksumMismatch { .. }) => {}
        other => panic!("expected the byte tier to reject, got {other:?}"),
    }
    // Prove the canonical tier was satisfied: the same envelope without
    // its byte_checksum region loads cleanly.
    let mut value: serde_json::Value = serde_json::from_str(&tampered).unwrap();
    value.as_object_mut().unwrap().remove("byte_checksum");
    PargArtifact::from_json(&serde_json::to_string(&value).unwrap())
        .unwrap_or_else(|err| panic!("canonical payload was intact: {err:?}"));
}

#[test]
fn extracts_and_parses_the_entry_grammar() {
    let artifact = PargArtifact::from_json(FIXTURE).unwrap();
    let grammar = artifact.grammar("identifier").unwrap();

    let mut arena = AstArena::for_input("ISO CD 12345-89".len());
    let mut parser = PortableParser::new(&grammar, "ISO CD 12345-89", &mut arena);
    parser.parse().expect("the fixture grammar accepts a pubid");

    let mut negative = AstArena::for_input("nonsense".len());
    let mut parser = PortableParser::new(&grammar, "nonsense", &mut negative);
    assert!(
        parser.parse().is_err(),
        "raw input must not parse as a pubid"
    );
}

#[test]
fn rejects_unknown_entries() {
    let artifact = PargArtifact::from_json(FIXTURE).unwrap();
    match artifact.grammar("nope") {
        Err(PargError::UnknownEntry(entry)) => assert_eq!(entry, "nope"),
        other => panic!("expected unknown entry, got {other:?}"),
    }
}

#[test]
fn canonical_json_round_trips_the_ruby_reference_bytes() {
    // The fixture file was generated by Ruby's JSON.generate over a
    // key-sorted payload; canonical_json must reproduce it byte for byte,
    // including lowercase \u00xx control escapes and raw UTF-8.
    let value: serde_json::Value = serde_json::from_str(CANONICAL_SAMPLE).unwrap();
    assert_eq!(canonical_json(&value).unwrap(), CANONICAL_SAMPLE.trim_end());
}

#[test]
fn canonical_json_renders_floats_like_the_ruby_json_gem() {
    // B6: floats canonicalize to the shortest round-trip digits in the
    // JSON gem's notation, so a Ruby-baked envelope with float
    // expectations verifies its checksum byte for byte.
    let value: serde_json::Value = serde_json::from_str("{\"x\":1.5,\"y\":2.0}").unwrap();
    assert_eq!(canonical_json(&value).unwrap(), "{\"x\":1.5,\"y\":2.0}");
}

/// The numeric edition surface (ruby#357): integers are canonical; the
/// quoted v-form stays loadable so artifacts baked before the numeric
/// surface remain readable. Absent = edition 2. Edition 1 was removed:
/// its spellings reject the artifact at load (see the removal test).
#[test]
fn normalizes_every_edition_spelling_that_has_shipped() {
    for (spelling, level) in [
        (serde_json::json!(2), 2u8),
        (serde_json::json!("2"), 2),
        (serde_json::json!("v2"), 2),
        (serde_json::json!(null), 2),
    ] {
        let artifact = resign_with_edition(&spelling)
            .unwrap_or_else(|err| panic!("spelling {spelling}: load failed: {err:?}"));
        assert_eq!(
            artifact.edition(),
            level,
            "spelling {spelling} must normalize to level {level}"
        );
    }
}

#[test]
fn rejects_the_removed_and_unknown_edition_spellings() {
    for spelling in [
        serde_json::json!(1),
        serde_json::json!("1"),
        serde_json::json!("v1"),
        serde_json::json!("classic"),
        serde_json::json!(3),
        serde_json::json!("future"),
    ] {
        match resign_with_edition(&spelling) {
            Err(PargError::InvalidEnvelope(_)) => {}
            other => panic!("spelling {spelling}: expected InvalidEnvelope, got {other:?}"),
        }
    }
}

/// Re-sign the fixture with the given edition spelling and load it.
fn resign_with_edition(spelling: &serde_json::Value) -> Result<PargArtifact, PargError> {
    let mut value: serde_json::Value = serde_json::from_str(FIXTURE).unwrap();
    value["edition"] = spelling.clone();
    value.as_object_mut().unwrap().remove("checksum");
    let computed = parsanol::parg::checksum_hex(&value).unwrap();
    value["checksum"] = serde_json::Value::String(computed);
    PargArtifact::from_json(&serde_json::to_string(&value).unwrap())
}

#[test]
fn checksum_refusal_names_the_compiler_version() {
    // rs#494: the refusal carries version guidance, not a bare error.
    let mut value: serde_json::Value = serde_json::from_str(FIXTURE).unwrap();
    value["version"] = serde_json::Value::String("9.9.9".into());
    let text = serde_json::to_string(&value).unwrap();
    let err = PargArtifact::from_json(&text).expect_err("tampered envelope must refuse");
    let message = err.to_string();
    assert!(
        message.contains("compiled by compiler"),
        "the refusal must name the producer: {message}"
    );
}
